# Runs for EVERY event once verify + e2e succeeded, so a pull request proves
# that its release still packages and boots (merging to main deploys). No
# secrets here; the artifact is only uploaded for main.
package-release:
  name: Package and smoke-test the release
  needs: [verify, e2e]
  if: needs.verify.result == 'success' && needs.e2e.result == 'success'
  runs-on: ubuntu-latest
  timeout-minutes: 30
  outputs:
    sha: ${{ steps.meta.outputs.sha }}
    archive: ${{ steps.archive.outputs.archive }}
    archive_sha256: ${{ steps.archive.outputs.sha256 }}

