export async function getAccountRelationship(
  prisma: PrismaClient,
  userId: string,
  accountId: string,
): Promise<AccountRelationship | null> {
  const grant = await prisma.accountAccess.findUnique({
    where: { userId_accountId: { userId, accountId } },
