/** Issue a new (simulated) card on an account. Audited; writes no ledger. */
export async function issueCard(
  user: SessionUser,
  accountId: string,
  input: NormalizedIssueCard,
  now: Date = new Date(),
): Promise<CardDTO> {
  await requireCardAccount(user.id, accountId);
  // Resource cap (all modes): bounded LIVE cards per account (terminal cards —
  // lost / stolen / replaced / cancelled — do not count).
  const live = await prisma.card.count({ where: { accountId, status: { in: ['active', 'frozen'] } } });
  if (live >= RESOURCE_CAPS.liveCardsPerAccount) {
    throw new CardError(
      'limit_reached',
      `This account already has ${RESOURCE_CAPS.liveCardsPerAccount} live cards (the simulated maximum).`,
    );
  }
  const { expMonth, expYear } = simulatedExpiry(now);
  const last4 = simulatedLast4();

  const created = await prisma.card.create({
    data: {
      accountId,
      userId: user.id,
      cardType: input.cardType,
      network: input.network,
      last4,
      expMonth,
      expYear,
      status: 'active',
      createdAt: now,
      updatedAt: now,
    },
    include: CARD_INCLUDE,
  });

  await writeAudit(prisma, {
    actorId: user.id,
    actorRole: user.role,
    action: 'card_issued',
    entity: 'card',
    entityId: created.id,
    reason: `Issued ${CARD_NETWORK_LABELS[input.network]} ${CARD_TYPE_LABELS[input.cardType].toLowerCase()} ••${last4} (simulated)`,
    metadata: { accountId, cardType: input.cardType, network: input.network, last4, actorName: user.displayName },
  });

  return toCardDTO(created);
}

