async function runAction(id: string, action: OpsAction) {
  setActionError(null);
  setBusyIds((prev) => new Set(prev).add(id));
  try {
    await act(id, action);
  } catch (err) {
    setActionError(err instanceof ApiError ? err.message : 'That action could not be completed.');
  } finally {
    setBusyIds((prev) => {
      const next = new Set(prev);
      next.delete(id);
      return next;
    });
  }
}

