    { amountMinor: 9_999, direction: 'debit', status: 'pending', at: at(2026, 5, 9) }, // within but NOT settled
    { amountMinor: 5_000, direction: 'credit', status: 'posted', at: at(2026, 6, 2) }, // after — ignored
  ];

